def discover_rows(c):
    """清单存在时仅使用清单；不同时扫描目录，避免重复摄入。"""
    if c["manifest_csv"]:
        manifest = Path(c["manifest_csv"])
        with manifest.open(encoding="utf-8-sig", newline="") as f:
            for row in csv.DictReader(f):
                if not row.get("path"):
                    raise ValueError("manifest 缺少 path")
                yield dict(row, path=str((manifest.parent / row["path"]).resolve()))
        return
    aliases = {"positive": "positive", "positives": "positive", "positive_wavs": "positive",
               "negative": "negative", "negatives": "negative", "negative_wavs": "negative"}
    for source in c["data_sources"]:
        root = Path(source["path"])
        if not root.is_dir():
            raise ValueError(f"数据目录不存在: {root}；请修改配置，不会静默跳过")
        for path in sorted(root.rglob("*")):
            if not path.is_file() or path.suffix.lower() != ".wav":
                continue
            relative = path.relative_to(root).as_posix()
            excludes = source.get("exclude", [])
            if any(relative == pat or relative.startswith(pat.rstrip("/") + "/")
                   or fnmatch.fnmatch(relative, pat) for pat in excludes):
                continue
            label = source["label"]
            if label == "auto":
                labels = {aliases[p.lower()] for p in path.relative_to(root).parts[:-1] if p.lower() in aliases}
                if len(labels) != 1:
                    raise ValueError(f"无法推断 TTS 标签: {path}；请分 positive/negative 子目录，或使用 CSV 清单")
                label = labels.pop()
            yield dict(path=str(path.resolve()), label=label, source=source["source"],
                       kind=source.get("kind", "unknown"))


def collect(c):
    records, duplicates, seen, recording_groups = [], [], {}, {}
    # 并查集合并重复片段关联的 group，避免同内容跨集合。
    parent = {}
    def root(group):
        parent.setdefault(group, group)
        while group != parent[group]:
            parent[group] = parent[parent[group]]
            group = parent[group]
        return group
    for row in discover_rows(c):
        path = Path(row["path"]).resolve()
        if row.get("label") not in ["positive", "negative"]:
            raise ValueError(f"无效 label: {path}")
        source = row.get("source", "real") or "real"
        kind = row.get("kind", "unknown") or "unknown"
        split = row.get("split", "") or ""
        if source not in ["real", "tts"] or kind not in ["unknown", "noise", "speech", "hard"]:
            raise ValueError(f"无效 source/kind: {path}")
        if split not in ["", "train", "validation", "test"]:
            raise ValueError(f"无效 split: {path}")
        if source == "tts" and split not in ["", "train"]:
            raise ValueError("TTS 只能放训练集；真人验证/测试集用于选择阈值和最终评估")
        audio = load_wav(path)
        duration = len(audio) / 16000
        start, end = float(row.get("start") or 0), float(row.get("end") or duration)
        if not (0 <= start < end <= duration + 1e-6):
            raise ValueError(f"start/end 无效: {path}")
        audio = audio[round(start * 16000):round(end * 16000)]
        label = int(row["label"] == "positive")
        if label and len(audio) > samples(c):
            raise ValueError(f"正样本区间超过 {c['window_seconds']}s: {path}；请在清单标 start/end，"
                             "确保完整唤醒词在区间内；禁止自动按最大能量裁剪")
        if not len(audio) or (label and np.max(np.abs(audio)) < 1 / 32768):
            raise ValueError(f"空音频或纯静音正样本: {path}")
        speaker = row.get("speaker_id", "").strip()
        manual_group = (row.get("group") or row.get("group_id") or "").strip()
        # speaker_id 全局生效；同说话人跨来源/跨 session 仍不跨集合。
        group = "speaker:" + speaker if speaker else ("group:" + manual_group if manual_group else "file:" + str(path))
        if source == "real" and c["require_speaker_groups"] and kind != "noise" and not speaker:
            raise ValueError(f"缺少 speaker_id: {path}；多人长录音用显式 split 隔离相同说话人")
        if str(path) in recording_groups:
            parent[root(group)] = root(recording_groups[str(path)])
        recording_groups[str(path)] = group
        digest = hashlib.sha256(audio.tobytes()).hexdigest()
        r = dict(path=str(path), label=label, source=source, kind=kind, split=split,
                 speaker_id=speaker, group=group, start=start, end=end, audio=audio, digest=digest)
        if digest in seen:
            previous = seen[digest]
            if previous["label"] != label:
                raise ValueError(f"相同 PCM 标签冲突: {path} / {previous['path']}")
            if previous["source"] != source:
                raise ValueError(f"相同 PCM 同时标为 real/tts: {path}；请修正来源再训练")
            if previous["split"] and split and previous["split"] != split:
                raise ValueError(f"重复 PCM 有冲突 split: {path}")
            previous["split"] = previous["split"] or split
            parent[root(group)] = root(previous["group"])
            duplicates.append(dict(path=str(path), kept=previous["path"], digest=digest))
            continue
        seen[digest] = r
        records.append(r)
    for r in records:
        r["group"] = root(r["group"])
    if any(sum(r["label"] == label and r["source"] == "real" for r in records) < 3 for label in [0, 1]):
        raise ValueError("真人正/负样本各需至少 3 条独立录音")
    return records, duplicates


def split_records(records, c):
    real = [r for r in records if r["source"] == "real"]
    synthetic = [r for r in records if r["source"] == "tts"]
    groups = sorted({r["group"] for r in real})
    if any(r["split"] for r in real):
        if not all(r["split"] for r in real):
            raise ValueError("使用显式 split 时，所有真人样本都必须填写 split")
        best = [[r for r in real if r["split"] == name] for name in ["train", "validation", "test"]]
    else:
        fractions = np.array([1 - c["validation_fraction"] - c["test_fraction"],
                              c["validation_fraction"], c["test_fraction"]])
        rng = np.random.default_rng(c["seed"])
        best, best_loss = None, float("inf")
        if len(groups) == len(real):
            best = [[], [], []]
            for label in [0, 1]:
                items = [r for r in real if r["label"] == label]
                rng.shuffle(items)
                nv, nt = max(1, round(len(items) * fractions[1])), max(1, round(len(items) * fractions[2]))
                if nv + nt >= len(items):
                    nv = nt = 1
                best[0].extend(items[nv + nt:])
                best[1].extend(items[:nv])
                best[2].extend(items[nv:nv + nt])
        else:
            counts = np.array([[sum(r["group"] == g and r["label"] == label for r in real)
                                for label in [0, 1]] for g in groups])
            target = fractions[:, None] * counts.sum(axis=0)
            for _ in range(10000):
                assignment = rng.choice(3, len(groups), p=fractions)
                actual = np.array([counts[assignment == k].sum(axis=0) for k in range(3)])
                if np.any(actual == 0):
                    continue
                loss = float(np.sum(((actual - target) / np.maximum(target, 1)) ** 2))
                if loss < best_loss:
                    mapping = dict(zip(groups, assignment))
                    best = [[r for r in real if mapping[r["group"]] == k] for k in range(3)]
                    best_loss = loss
    if best is None or any(not subset or len({r["label"] for r in subset}) != 2 for subset in best):
        raise ValueError("无法划分均含正负样本的真人训练/验证/测试集；请增加独立说话人/组")
    best[0].extend(synthetic)
    group_sets = [{r["group"] for r in subset} for subset in best]
    if any(group_sets[i] & group_sets[j] for i, j in [(0, 1), (0, 2), (1, 2)]):
        raise ValueError("同说话人/同录音组出现在多个 split（含 TTS），请修正清单")
    return best


MANIFEST_FIELDS = ["path", "label", "source", "kind", "speaker_id", "group", "start", "end", "split"]


def write_manifest(path, subsets, names):
    with Path(path).open("x", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=MANIFEST_FIELDS)
        writer.writeheader()
        for subset, name in zip(subsets, names):
            for r in subset:
                row = {k: r.get(k, "") for k in MANIFEST_FIELDS}
                row["label"] = ["negative", "positive"][r["label"]]
                row["split"] = name or r.get("split", "")
                # file: 后备 group 不写回，便于后续正确填写 speaker_id。
                row["group"] = "" if r["group"].startswith(("file:", "speaker:")) else r["group"].removeprefix("group:")
                writer.writerow(row)


def dataset_summary(records, duplicates, subsets):
    def counts(rs):
        return {f"{source}_{label}": sum(r["source"] == source and r["label"] == y for r in rs)
                for source in ["real", "tts"] for y, label in enumerate(["negative", "positive"])}
    fallback = sum(r["source"] == "real" and not r["speaker_id"] and r["kind"] != "noise" for r in records)
    if fallback:
        warn(f"{fallback} 条真人语音未标 speaker_id；当前只能保证 group/文件不重叠，不能证明未见说话人泛化")
    if not any(r["kind"] == "noise" and not r["label"] for r in subsets[0]):
        warn("训练集没有 kind=noise 的纯背景音，背景混音关闭；不会擅自把讲话负样本当纯噪声")
    return dict(unique_files=len(records), dropped_duplicates=len(duplicates), totals=counts(records),
                splits={name: dict(counts(subset), groups=len({r['group'] for r in subset}))
                        for name, subset in zip(["train", "validation", "test"], subsets)},
                real_without_speaker_id=fallback, duplicate_details=duplicates,
                deduplication="exact PCM segment SHA256; near-duplicates require manual audit")


def rms(audio):
    return float(np.sqrt(np.mean(np.asarray(audio, np.float64) ** 2)))


def fit_window(audio, c, rng=None):
    size = samples(c)
    if len(audio) > size:
        start = int(rng.integers(len(audio) - size + 1)) if rng is not None else len(audio) - size
        return audio[start:start + size].copy()
    gap = size - len(audio)
    left = int(rng.integers(gap + 1)) if rng is not None else gap  # 对齐因果窗口的右边界
    return np.pad(audio, (left, gap - left)).astype(np.float32)


