const rs = await Promise.allSettled([
  tools.exec_command({cmd:"find runs -maxdepth 2 -type f -printf '%p\\n' | sort | head -250","workdir":"/home/foam/下载/openvela_wakeword","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({cmd:"rg -n \"afe_mode|confirm_hits|threshold_override|board_v3|manifest_csv|def train|def collect|data_sources\" wakeword.py | head -120","workdir":"/home/foam/下载/openvela_wakeword","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"sed -n '1,180p' config_esp32s3_all_data.json; printf '%s\\n' '---50---'; sed -n '1,180p' config_esp32s3_no_mimo_positive_50_mimo_negative.json; printf '%s\\n' '---100---'; sed -n '1,180p' config_esp32s3_no_mimo_positive_100_mimo_negative.json; printf '%s\\n' '---real---'; sed -n '1,180p' config_esp32s3_real_only.json","workdir":"/home/foam/下载/openvela_wakeword","yield_time_ms":10000,"max_output_tokens":30000})
]);
for (const r of rs) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json
from pathlib import Path
base=json.loads(Path('config_esp32s3.json').read_text())
for p in sorted(Path('.').glob('config_esp32s3*.json')):
 d=json.loads(p.read_text())
 print(p.name, 'missing', sorted(set(base)-set(d)), 'extra', sorted(set(d)-set(base)), 'same_except_manifest_output', all(d.get(k)==base.get(k) for k in set(base)-{'manifest_csv','output_dir'}))
PY
printf '%s\n' '--- prepare program help ---'; .venv/bin/python prepare_wakeword_model.py --help 2>&1 | head -80","workdir":"/home/foam/下载/openvela_wakeword","yield_time_ms":10000,"max_output_tokens":10000});
text(r.output);

const r = await tools.exec_command({cmd:"rm -rf -- runs/openvela_dscnn_all_data runs/openvela_dscnn_no_mimo_positive_50_mimo_negative runs/openvela_dscnn_real_only runs/openvela_dscnn_no_mimo_positive_100_mimo_negative
printf '%s\n' 'remaining target dirs:'
for d in runs/openvela_dscnn_all_data runs/openvela_dscnn_no_mimo_positive_50_mimo_negative runs/openvela_dscnn_real_only runs/openvela_dscnn_no_mimo_positive_100_mimo_negative; do test -e "$d" && echo "$d EXISTS" || echo "$d removed"; done
.venv/bin/python -m py_compile wakeword.py prepare_wakeword_model.py","workdir":"/home/foam/下载/openvela_wakeword","yield_time_ms":10000,"max_output_tokens":5000});
text(r.output);

const configs = [
  "config_esp32s3_all_data.json",
  "config_esp32s3_no_mimo_positive_50_mimo_negative.json",
  "config_esp32s3_real_only.json",
  "config_esp32s3_no_mimo_positive_100_mimo_negative.json"
];
const rs = await Promise.all(configs.map(c => tools.exec_command({
  cmd:`.venv/bin/python wakeword.py audit --config ${c}`,
  workdir:"/home/foam/下载/openvela_wakeword",
  yield_time_ms:1000,
  max_output_tokens:8000
})));
for (let i=0;i<rs.length;i++){ text(`--- ${configs[i]} ---`); text(rs[i].output); }

