def trace_metrics(records, traces, c, threshold):
    predictions = []
    for trace in traces:
        _, events = replay([r["raw_score"] for r in trace], [r["rms"] for r in trace],
                           [r["end_seconds"] for r in trace], c, threshold)
        predictions.append(bool(events))
    return statistics([r["label"] for r in records], predictions, .5)


def evaluate(records, score_fn, front, c):
    traces = evaluate_traces(records, score_fn, front, c)
    return (np.asarray([r["label"] for r in records]),
            np.asarray([confirmation_score([t["score"] for t in trace],c) for trace in traces]))


def select_threshold(records, traces, c):
    if c["auto_threshold"]:
        grid = sorted(set(float(np.float32(t)) for t in np.r_[np.linspace(c["threshold_min"],1,141),c["threshold"]]))
    else:
        grid = [effective_threshold(c,c["threshold"])]
    sweep = [dict(threshold=t, **trace_metrics(records,traces,c,t)) for t in grid]
    threshold = grid[0]
    if c["auto_threshold"]:
        candidates = [m for m in sweep if m["false_positive_rate"] <= c["max_validation_fpr"] + 1e-10]
        if not candidates:
