#ifndef ROBOT_WAKEWORD_INPUT_QUANTIZE_H
#define ROBOT_WAKEWORD_INPUT_QUANTIZE_H
#include <stdint.h>
#include <stddef.h>
#include <math.h>
/* Independent of ambient rounding mode. Float32 divide then add, nearest even. */
static inline int robot_wakeword_quantize_input(const float *x, size_t n,
                                               float scale, int zero, int8_t *out) {
  if (!x || !out || !(scale>0) || !isfinite(scale) || zero < -128 || zero > 127) return -1;
  for (size_t i=0;i<n;i++) {
    if (!isfinite(x[i])) return -1;
    volatile float divided=x[i]/scale;
    float value=divided+(float)zero;
    if (value<=-128) out[i]=-128;
    else if (value>=127) out[i]=127;
    else {
      float base=floorf(value), delta=value-base;
      int rounded=(int)base;
      if (delta>.5f || (delta==.5f && (rounded%2)!=0)) rounded++;
      out[i]=(int8_t)rounded;
    }
  }
  return 0;
}
#endif
#pragma once
#include <math.h>
#include <stddef.h>
#include <stdint.h>
/* Optional adapter for the existing (not supplied) TFLM model_predict code.
 * Read scale/zero_point from the actual model input tensor on every new model.
 * Explicit nearest-even ties; does not depend on the thread's fenv rounding mode.
 */
static inline int RobotWakewordQuantizeInput(const float *features, size_t count,
                                            float scale, int zero_point, int8_t *out)
{
  if (!features || !out || !isfinite(scale) || scale <= 0 ||
      zero_point < -128 || zero_point > 127) return -1;
  for (size_t i = 0; i < count; ++i) {
    float q = features[i] / scale + (float)zero_point;
    if (!isfinite(q)) return -1;
    if (q <= -128) out[i] = -128;
    else if (q >= 127) out[i] = 127;
    else {
      float low = floorf(q), fraction = q - low;
      int value = (int)low;
      if (fraction > 0.5f || (fraction == 0.5f && value % 2 != 0)) ++value;
      out[i] = (int8_t)value;
    }
  }
  return 0;
}
